    if (ux >= 0x7F800000) return x - x;

    // general argument reduction needed
    let n = rempio2f(x, ux, sign);
    let y = rempio2f_y;

    let t = n & 1 ? sin_kernf(y) : cos_kernf(y);
    return (n + 1) & 2 ? -t : t;
