  let w_exp = umul64e(exp, exp_pow);

  let wp_frc = umul64f(_frc_plus, frc_pow) - 1;
  let wp_exp = umul64e(_exp, exp_pow);

  let wm_frc = umul64f(_frc_minus, frc_pow) + 1;
